export function createGroupManagementUI({api,onOpenJoin=()=>{}}){
 let user=null,timer=null,generation=0,busy=false,data=null,pendingReload=false;
 const dialog=document.createElement('dialog');dialog.className='admin-console group-management';dialog.setAttribute('aria-label','群聊管理');dialog.innerHTML=`<header><strong>群聊管理</strong><div><button type="button" data-join>入群设置与申请</button><button type="button" data-close aria-label="关闭群聊管理">×</button></div></header><section class="group-body"><div class="group-toolbar"><input data-search placeholder="搜索昵称或用户名" aria-label="搜索成员"><select data-filter aria-label="成员状态"><option value="approved">群成员</option><option value="kicked">已移出</option></select><button type="button" data-refresh>刷新</button></div><p data-summary></p><div data-members></div><p data-status role="status"></p></section>`;document.body.append(dialog);const list=dialog.querySelector('[data-members]'),status=dialog.querySelector('[data-status]'),search=dialog.querySelector('[data-search]'),filter=dialog.querySelector('[data-filter]');
 const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
 function render(){if(!data)return;const query=search.value.trim().toLowerCase(),members=data.members.filter(m=>m.membership===filter.value&&(!query||(m.displayName+' '+m.username).toLowerCase().includes(query)));dialog.querySelector('[data-summary]').textContent=data.members.filter(m=>m.membership==='approved').length+' 位成员 · '+data.day+'（香港时间）'+(data.unattributedTokens?' · 历史未归属 '+data.unattributedTokens.toLocaleString()+' token':'');list.replaceChildren();if(!members.length){list.textContent='没有匹配的成员';return;}
  for(const member of members){const row=el('article','group-member'),identity=el('div','group-identity'),avatar=el('div','group-avatar',member.displayName?.[0]||'人');if(member.avatarUrl){const image=el('img');image.src=member.avatarUrl;image.alt=member.displayName;image.referrerPolicy='no-referrer';image.onerror=()=>avatar.textContent=member.displayName?.[0]||'人';avatar.replaceChildren(image);}const copy=el('div'),name=el('strong','',member.displayName),username=el('small','','@'+member.username),muted=member.mutedUntil===-1||member.mutedUntil>Date.now();copy.append(name,username,el('small','',member.membership==='kicked'?'已移出':member.role==='admin'?'管理员':muted?member.mutedUntil===-1?'长期禁言':'禁言至 '+new Date(member.mutedUntil).toLocaleString('zh-CN',{timeZone:'Asia/Hong_Kong'}):'成员'));identity.append(avatar,copy);
   const usage=el('div','group-usage');usage.append(el('span','','今日 '+member.usage.today.toLocaleString()+' token'),el('small','','累计 '+member.usage.total.toLocaleString()+' token'));if(member.usage.reserved)usage.append(el('small','','预留 / 未回传 '+member.usage.reserved.toLocaleString()));
   const quota=el('div','group-quota'),label=el('label','','每日上限'),limit=el('input');limit.type='number';limit.min='0';limit.max='1000000000';limit.step='1';limit.placeholder='不限';limit.value=member.dailyTokenLimit??'';limit.setAttribute('aria-label',member.displayName+'每日 token 上限');const save=el('button','','保存上限');save.type='button';label.append(limit);quota.append(label,save);
   async function action(body){const stamp=++generation;for(const button of row.querySelectorAll('button,input,select'))button.disabled=true;try{await api('/api/admin/group/manage',{method:'POST',body:{userId:member.id,...body}});if(stamp===generation){status.textContent='已更新';await load();}}catch(error){if(stamp===generation){status.textContent=error.message;render();}}}
   save.onclick=()=>{const value=limit.value.trim()===''?null:Number(limit.value);if(value!==null&&(!Number.isSafeInteger(value)||value<0||value>1e9)){status.textContent='请输入有效的每日上限，0 或留空表示不限';return;}void action({action:'quota',dailyTokenLimit:value});};
   const actions=el('div','group-actions');if(member.membership==='kicked'){limit.disabled=true;save.disabled=true;}else if(member.role!=='admin'){
    const duration=el('select');duration.setAttribute('aria-label',member.displayName+'禁言时长');for(const [value,text] of [[10,'10 分钟'],[60,'1 小时'],[1440,'1 天'],[0,'长期']]){const option=el('option','',text);option.value=String(value);duration.append(option);}duration.value='60';const mute=el('button','',muted?'解除禁言':'禁言');mute.type='button';mute.onclick=()=>void action(muted?{action:'unmute'}:{action:'mute',durationMinutes:Number(duration.value)});const kick=el('button','danger','踢出'),cancel=el('button','','取消');kick.type=cancel.type='button';cancel.hidden=true;cancel.onclick=()=>{kick.textContent='踢出';kick.dataset.confirm='';cancel.hidden=true;};kick.onclick=()=>{if(kick.dataset.confirm==='yes')void action({action:'kick'});else{kick.dataset.confirm='yes';kick.textContent='确认踢出';cancel.hidden=false;}};if(!muted)actions.append(duration);actions.append(mute,kick,cancel);
   }row.append(identity,usage,quota,actions);list.append(row);
  }
 }
 async function load(){if(!dialog.open||user?.role!=='admin')return;if(busy){pendingReload=true;return;}const stamp=generation;busy=true;try{const result=await api('/api/admin/group/members');if(stamp!==generation||!dialog.open)return;data=result;render();}catch(error){if(stamp===generation)status.textContent=error.message;}finally{busy=false;if(pendingReload){pendingReload=false;void load();}}}
 search.oninput=filter.onchange=render;dialog.querySelector('[data-refresh]').onclick=()=>void load();dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('[data-join]').onclick=()=>{dialog.close();onOpenJoin();};dialog.addEventListener('close',()=>{clearInterval(timer);timer=null;});
 return {setUser(next){if(next?.id!==user?.id||next?.role!=='admin'){generation++;data=null;list.replaceChildren();if(dialog.open)dialog.close();}user=next;},open(){if(user?.role!=='admin')return;if(!dialog.open)dialog.showModal();status.textContent='';void load();clearInterval(timer);timer=setInterval(()=>{if(!dialog.querySelector('input:focus,select:focus,[role=combobox][aria-expanded=true]')&&!dialog.querySelector('[data-confirm=yes]'))void load();},10000);},close(){generation++;data=null;list.replaceChildren();dialog.close();}};
}
